1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Tags\Support;
6	
7	use Illuminate\Database\Eloquent\Model;
8	use Illuminate\Support\Str;
9	use RuntimeException;
10	
11	/**
12	 * Registro delle entità taggabili, config-driven. Il core non conosce i modelli
13	 * di dominio (Product, Material, … sono app-level): l'app dichiara la mappa
14	 * `alias => classe` in `config('digital-hub.taggable_entities')`. L'alias è il
15	 * morph alias del modello (coincide con `taggables.taggable_type`), così il
16	 * filtro dei tag per entità è una semplice uguaglianza di stringa.
17	 */
18	class TaggableEntities
19	{
20	    /**
21	     * Mappa alias => class-string dei modelli entità taggabili.
22	     *
23	     * @return array<string, class-string<Model>>
24	     */
25	    public static function map(): array
26	    {
27	        /** @var array<string, class-string<Model>> $map */
28	        $map = (array) config('digital-hub.taggable_entities', []);
29	
30	        return $map;
31	    }
32	
33	    /**
34	     * @return class-string<Model>
35	     */
36	    public static function modelClass(string $alias): string
37	    {
38	        $class = self::map()[$alias] ?? null;
39	
40	        if ($class === null) {
41	            throw new RuntimeException("Entità taggabile non registrata per l'alias [{$alias}]. Aggiungila in config('digital-hub.taggable_entities').");
42	        }
43	
44	        return $class;
45	    }
46	
47	    /**
48	     * Alias (morph) di un modello entità.
49	     */
50	    public static function aliasFor(Model $model): string
51	    {
52	        return $model->getMorphClass();
53	    }
54	
55	    public static function label(string $alias): string
56	    {
57	        $key = 'digital-hub::tag_group.entities.' . $alias;
58	        $label = __($key);
59	
60	        return is_string($label) && $label !== $key ? $label : Str::headline($alias);
61	    }
62	
63	    /**
64	     * Opzioni per la Select Filament: [alias => label].
65	     *
66	     * @return array<string, string>
67	     */
68	    public static function options(): array
69	    {
70	        $options = [];
71	
72	        foreach (array_keys(self::map()) as $alias) {
73	            $options[$alias] = self::label($alias);
74	        }
75	
76	        return $options;
77	    }
78	}
