5	namespace AtrioTeam\DigitalHub\Tags\Filament;
6	
7	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
8	use AtrioTeam\DigitalHub\Tags\Models\Tag;
9	use Filament\Forms\Components\Select;
10	use Illuminate\Database\Eloquent\Builder;
11	
12	/**
13	 * Select dei tag associabili, con vincolo rigido: mostra solo i tag il cui
14	 * gruppo è filtrato per l'entità data e per il target dato (entity|asset).
15	 * Ogni opzione mostra la categoria di appartenenza nell'etichetta
16	 * (es. "Materiale › Legno"). Condiviso fra i form delle entità e il picker
17	 * degli asset nell'AssetManager.
18	 */
19	class TagPicker
20	{
21	    /**
22	     * Picker legato alla relazione `tags` del record del form (entità che usa
23	     * HasTags): Filament sincronizza da sé il pivot `taggables`.
24	     *
25	     * Con relationship() Filament costruisce le opzioni dalla query della
26	     * relazione: la label si personalizza via getOptionLabelFromRecordUsing()
27	     * e il filtro (entity_type, target) via modifyQueryUsing().
28	     */
29	    public static function make(string $entityAlias, TagTarget $target): Select
30	    {
31	        return self::base()
32	            // HasTags espone tags() come MorphToMany: Filament sincronizza il pivot.
33	            // I tag si gestiscono dalla loro resource, qui si associano solo esistenti.
34	            ->relationship(
35	                name: 'tags',
36	                titleAttribute: 'name',
37	                modifyQueryUsing: fn (Builder $query): Builder => self::scopeToGroup($query, $entityAlias, $target),
38	            )
39	            ->getOptionLabelFromRecordUsing(fn (Tag $record): string => self::optionLabel($record));
40	    }
41	
42	    /**
43	     * Picker "standalone" (senza relationship): lo stato è un array di id tag.
44	     * Per contesti senza record bindato al form (es. azione nell'AssetManager),
45	     * dove fill/sync sono gestiti a mano dal chiamante.
46	     */
47	    public static function makeStandalone(string $entityAlias, TagTarget $target): Select
48	    {
49	        return self::base()
50	            ->options(fn (): array => self::groupedOptions($entityAlias, $target));
51	    }
52	
53	    private static function base(): Select
54	    {
55	        return Select::make('tags')
56	            ->label(__('digital-hub::tag.model_plural'))
57	            ->multiple()
58	            ->searchable()
59	            ->preload();
60	    }
61	
62	    /**
63	     * Restringe la query dei tag ai soli gruppi filtrati per entità e target.
64	     *
65	     * @param Builder<Tag> $query
66	     * @return Builder<Tag>
67	     */
68	    private static function scopeToGroup(Builder $query, string $entityAlias, TagTarget $target): Builder
69	    {
70	        return $query->whereHas('category.group', fn (Builder $groupQuery) => $groupQuery
71	            ->where('entity_type', $entityAlias)
72	            ->where('target', $target->value));
73	    }
74	
75	    /**
76	     * Etichetta con categoria di appartenenza in testa (es. "Materiale › Legno").
77	     */
78	    private static function optionLabel(Tag $tag): string
79	    {
80	        $category = $tag->category !== null ? (string) $tag->category->name : (string) __('digital-hub::tag.ungrouped');
81	
82	        return $category . ' › ' . (string) $tag->name;
83	    }
84	
85	    /**
86	     * Opzioni per la variante standalone: id => "Categoria › Tag".
87	     * Solo i tag dei gruppi (entity_type, target).
88	     *
89	     * @return array<int, string>
90	     */
91	    private static function groupedOptions(string $entityAlias, TagTarget $target): array
92	    {
93	        $options = [];
94	
95	        $tags = self::scopeToGroup(Tag::query(), $entityAlias, $target)
96	            ->with('category')
97	            ->get();
98	
99	        foreach ($tags as $tag) {
100	            $options[(int) $tag->id] = self::optionLabel($tag);
101	        }
102	
103	        return $options;
104	    }
105	}
